</label>

@if (loginForm.password().touched() && loginForm.password().invalid()) {
<ul class="error-list">
@for (error of loginForm.password().errors(); track error) {
<li>{{ error.message }}</li>
}
</ul>
}
</div>

<button type="submit" [disabled]="loginForm().invalid()">Log In</button>
</form>

